package dev.eugheist.tc4modern;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class ElementalSwordAudit {
 static int ticks;static volatile boolean ready,finished;static ItemStack sword;static final BlockPos POS=InfusionAudit.POS;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_SWORD FAIL "+s);System.out.println("TC4_SWORD PASS "+s);}
 static void prepare(ServerPlayer p){p.getInventory().selected=0;InfusionAudit.prepare(p);RunicAudit.clear(p);InfusionAudit.matrix.logic.crafting=false;var l=p.serverLevel();l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);ElementalToolsAudit.start(p,"ElementalSword");sword=new ItemStack(ElementalTools.item("sword"));p.setItemInHand(InteractionHand.MAIN_HAND,sword);check(sword.getMaxDamage()==1500&&sword.getEnchantmentValue()==18&&sword.getItem().isValidRepairItem(sword,new ItemStack(TC4Modern.THAUMIUM.get())),"original1500durability18enchant thaumium repair");p.setDeltaMovement(0,-.6,0);p.fallDistance=12;p.startUsingItem(InteractionHand.MAIN_HAND);sword.getItem().onUseTick(l,p,sword,72000);check(Math.abs(p.getDeltaMovement().y-(-.6/1.2f+.08f))<.00001&&Math.abs(p.fallDistance-10)<.00001&&sword.getDamageValue()==1,"wind originalfall/1.2+.08 +fallDistance/1.2 anddurability at0");p.setDeltaMovement(0,.49,0);sword.getItem().onUseTick(l,p,sword,71999);check(Math.abs(p.getDeltaMovement().y-.2)<.00001&&sword.getDamageValue()==1,"wind originalovershoot>.5resets.2 andnoextra durability");
  p.invulnerableTime=0;p.setHealth(20);p.hurt(p.damageSources().mobAttack(EntityType.HUSK.create(l)),8);System.out.println("TC4_SWORD block health="+p.getHealth()+" absorption="+p.getAbsorptionAmount()+" blocking="+ElementalSword.blocking(p));check(p.getHealth()==15.5f,"legacy sword blocking8 becomes4.5 damage, not modern shield immunity");p.invulnerableTime=0;p.setHealth(20);p.hurt(p.damageSources().magic(),8);check(p.getHealth()==12,"original unblockablemagic unaffected by blocking");p.stopUsingItem();p.invulnerableTime=0;p.setHealth(20);p.fallDistance=0;p.setOnGround(true);p.setDeltaMovement(Vec3.ZERO);p.doTick();System.out.println("TC4_SWORD attack="+p.getAttributeValue(Attributes.ATTACK_DAMAGE)+" base="+p.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue()+" modifiers="+p.getAttribute(Attributes.ATTACK_DAMAGE).getModifiers());check(Math.abs(p.getAttributeValue(Attributes.ATTACK_DAMAGE)-8)<.00001,"original sword material3+4+player1 gives8 attack");
  var primary=EntityType.HUSK.create(l);var extra=EntityType.COW.create(l);var own=EntityType.WOLF.create(l);for(var mob:new Mob[]{primary,extra,own}){mob.setNoAi(true);mob.getAttribute(Attributes.MAX_HEALTH).setBaseValue(40);mob.setHealth(40);mob.getAttribute(Attributes.ARMOR).setBaseValue(0);mob.moveTo(p.getX(),p.getY(),p.getZ()+1,0,0);l.addFreshEntity(mob);}own.setOwnerUUID(p.getUUID());own.setTame(true,false);own.setHealth(40);p.resetAttackStrengthTicker();p.attack(primary);check(extra.getHealth()==32&&own.getHealth()==40&&primary.getHealth()<40,"actual primary attack adds full8secondary despite exhaustedcooldown, ownpet excluded");primary.discard();extra.discard();own.discard();
  var sharp=sword.copy();sharp.enchant(p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SHARPNESS),2);var sharpTarget=EntityType.HUSK.create(l);sharpTarget.getAttribute(Attributes.ARMOR).setBaseValue(0);sharpTarget.getAttribute(Attributes.MAX_HEALTH).setBaseValue(40);sharpTarget.setHealth(40);ElementalSword.attack(p,sharpTarget,sharp);check(sharpTarget.getHealth()==29.5f,"legacy secondary SharpnessII adds2.5 to8 damage");
  var bane=sword.copy();bane.enchant(p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.BANE_OF_ARTHROPODS),2);bane.enchant(p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.FIRE_ASPECT),2);var spider=EntityType.SPIDER.create(l);spider.getAttribute(Attributes.MAX_HEALTH).setBaseValue(40);spider.setHealth(40);ElementalSword.attack(p,spider,bane);check(spider.getHealth()==27&&!spider.hasEffect(net.minecraft.world.effect.MobEffects.MOVEMENT_SLOWDOWN)&&spider.getRemainingFireTicks()==160,"original secondary BaneII adds5 but doesNOTapply slow, FireAspectII8seconds");

  var pushed=EntityType.COW.create(l);pushed.setNoAi(true);pushed.moveTo(p.getX()+1,p.getY(),p.getZ(),0,0);l.addFreshEntity(pushed);pushed.setDeltaMovement(Vec3.ZERO);p.startUsingItem(InteractionHand.MAIN_HAND);sword.getItem().onUseTick(l,p,sword,71980);check(Math.abs(pushed.getDeltaMovement().x-1/2.5/1.1)<.00001,"wind original radial acceleration 1/2.5/(distance+.1)");p.stopUsingItem();pushed.discard();sword.setDamageValue(0);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.connection.teleport(POS.getX()+5,POS.getY()+1,POS.getZ()-6,30,18);ready=true;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.swordAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var server=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)server.execute(()->prepare(server.getPlayerList().getPlayer(id)));if(ticks==140){check(ready,"server sword mechanics finished");mc.options.keyUse.setDown(true);mc.gameMode.useItem(mc.player,InteractionHand.MAIN_HAND);mc.options.setCameraType(net.minecraft.client.CameraType.THIRD_PERSON_BACK);}if(ticks==155){System.out.println("TC4_SWORD clientusing="+mc.player.isUsingItem()+" spawned="+ElementalSwordClient.spawned+" rendered="+ElementalSwordClient.rendered+" key="+mc.options.keyUse.isDown());check(ElementalSwordClient.spawned>=50&&ElementalSwordClient.rendered>50,"original five wind spirals perclienttick");LiquidDeathAudit.shot(mc,"elemental-sword-wind.png");}if(ticks==165){mc.options.keyUse.setDown(false);mc.gameMode.releaseUsingItem(mc.player);mc.options.setCameraType(net.minecraft.client.CameraType.FIRST_PERSON);}if(ticks==175)server.execute(()->{var p=server.getPlayerList().getPlayer(id);check(sword.getDamageValue()>=1&&!p.isUsingItem(),"actual use-item packet sustains wind and release stops server");});if(ticks==180&&Boolean.getBoolean("tc4modern.swordQuickAuditOnly")){mc.stop();return;}if(ticks==850)server.execute(()->{ElementalToolsAudit.finish(server.getPlayerList().getPlayer(id),"ElementalSword");finished=true;});if(ticks==870){check(finished,"natural sword infusion finished");var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch("ELEMENTALSWORD"),0);mc.setScreen(book);}if(ticks==880)LiquidDeathAudit.shot(mc,"elemental-sword-book.png");if(ticks==890)mc.stop();}
}
